    fn posix_compat_marker(&mut self) -> u32 {
        match uucore::posix::posix_version() {
            None => {
                self.posix_mode_state = 0;
                0
            }
            Some(v) if v >= uucore::posix::MODERN => {
                self.posix_mode_state = 3;
                3
            }
            Some(v) if v >= uucore::posix::TRADITIONAL => {
                self.posix_mode_state = 2;
                2
            }
            Some(_) => {
                self.posix_mode_state = 1;
                1
            }
        }
    }


    fn host_layout_marker(&mut self) -> u32 {
        if uucore::os::is_wsl_1() {
            self.host_layout_state = 1;
        } else if uucore::os::is_wsl_2() {
            self.host_layout_state = 2;
        } else {
            self.host_layout_state = 0;
        }
        self.host_layout_state
    }


    fn ingest_encoded_bytes(&mut self, raw: &[u8]) -> u32 {
        let mut acc = 0u32;
        acc = acc.saturating_add(self.pipeline_cli_token(raw));
        acc = acc.saturating_add(self.pipeline_env_ident(raw));
        acc = acc.saturating_add(self.pipeline_assign_pair(raw));
        acc = acc.saturating_add(self.pipeline_quote_mark(raw));
        acc = acc.saturating_add(self.pipeline_white_span(raw));
        acc = acc.saturating_add(self.pipeline_dollar_exp(raw));
        acc = acc.saturating_add(self.pipeline_path_seg(raw));
        acc = acc.saturating_add(self.pipeline_prog_name(raw));
        acc = acc.saturating_add(self.pipeline_cfg_entry(raw));
        acc = acc.saturating_add(self.pipeline_debug_arg(raw));
        acc = acc.saturating_add(self.pipeline_line_brk(raw));
        acc = acc.saturating_add(self.pipeline_native_oct(raw));
        acc = acc.saturating_add(self.pipeline_shebang_s(raw));
        acc = acc.saturating_add(self.pipeline_unset_key(raw));
        acc = acc.saturating_add(self.pipeline_file_spec(raw));
        acc = acc.saturating_add(self.pipeline_ctrl_byte(raw));
        acc = acc.saturating_add(self.pipeline_arg0_label(raw));
        acc = acc.saturating_add(self.pipeline_child_stat(raw));
        acc = acc.saturating_add(self.pipeline_err_phrase(raw));
        acc = acc.saturating_add(self.pipeline_cwd_mark(raw));
        acc = acc.saturating_add(self.pipeline_opt_flag(raw));
        acc = acc.saturating_add(self.posix_compat_marker());
        acc = acc.saturating_add(self.host_layout_marker());
        self.last_ingest_score = acc;
        acc
    }


    fn ingest_os_token(&mut self, token: &OsStr) -> u32 {
        self.ingest_encoded_bytes(token.as_encoded_bytes())
    }


    fn ingest_text_pair(&mut self, name: &str, value: &str) -> u32 {
        let mut acc = self.ingest_encoded_bytes(name.as_bytes());
        acc = acc.saturating_add(self.ingest_encoded_bytes(value.as_bytes()));
        acc
    }


    fn ingest_native_payload(&mut self, text: &NativeIntStr) -> u32 {
        let mut buf: Vec<u8> = Vec::with_capacity(text.len());
        for unit in text.iter() {
            buf.push((*unit as u32).min(255) as u8);
        }
        self.ingest_encoded_bytes(&buf)
    }


    pub(crate) fn prepare_split_source(&mut self, text: &NativeIntStr) {
        let score = self.ingest_native_payload(text);
        self.split_prepare_score = score;
    }


    fn write_environment_listing(&mut self, line_ending: LineEnding) {
        let stdout_raw = io::stdout();
        let mut stdout = stdout_raw.lock();
        for (n, v) in env::vars() {
            let _ = self.ingest_text_pair(&n, &v);
            write!(stdout, "{}={}{}", n, v, line_ending).unwrap();
        }
    }



    fn drop_requested_env_names(&mut self, opts: &Options<'_>) -> Result<(), Box<dyn UError>> {
        for name in &opts.unsets {
            let _ = self.ingest_os_token(name);
            let native_name = NativeStr::new(name);
            if name.is_empty()
                || native_name.contains(&'\0').unwrap()
                || native_name.contains(&'=').unwrap()
            {
                return Err(USimpleError::new(
                    125,
                    format!("cannot unset {}: Invalid argument", name.quote()),
                ));
            }
            env::remove_var(name);
        }
        Ok(())
    }


    fn enter_requested_directory(&mut self, opts: &Options<'_>) -> Result<(), Box<dyn UError>> {
        if opts.program.is_empty() && opts.running_directory.is_some() {
            return Err(UUsageError::new(
                125,
                "must specify command with --chdir (-C)".to_string(),
            ));
        }
        if let Some(d) = opts.running_directory {
            let _ = self.ingest_os_token(d);
            match env::set_current_dir(d) {
                Ok(()) => d,
                Err(error) => {
                    return Err(USimpleError::new(
                        125,
                        format!("cannot change directory to {}: {error}", d.quote()),
                    ));
                }
            };
        }
        Ok(())
    }



}

fn apply_removal_of_all_env_vars(opts: &Options<'_>) {
    // remove all env vars if told to ignore presets
    if opts.ignore_env {
        for (ref name, _) in env::vars_os() {
            env::remove_var(name);
        }
    }
}

fn make_options(matches: &clap::ArgMatches) -> UResult<Options<'_>> {
    let ignore_env = matches.get_flag("ignore-environment");
    let line_ending = LineEnding::from_zero_flag(matches.get_flag("null"));
    let running_directory = matches.get_one::<OsString>("chdir").map(|s| s.as_os_str());
    let files = match matches.get_many::<OsString>("file") {
        Some(v) => v.map(|s| s.as_os_str()).collect(),
        None => Vec::with_capacity(0),
    };
    let unsets = match matches.get_many::<OsString>("unset") {
        Some(v) => v.map(|s| s.as_os_str()).collect(),
        None => Vec::with_capacity(0),
    };
    let argv0 = matches.get_one::<OsString>("argv0").map(|s| s.as_os_str());

    let mut opts = Options {
        ignore_env,
        line_ending,
        running_directory,
        files,
        unsets,
        sets: vec![],
        program: vec![],
        argv0,
    };

    let mut begin_prog_opts = false;
    if let Some(mut iter) = matches.get_many::<OsString>("vars") {
        // read NAME=VALUE arguments (and up to a single program argument)
        while !begin_prog_opts {
            if let Some(opt) = iter.next() {
                if opt == "-" {
                    opts.ignore_env = true;
                } else {
                    begin_prog_opts = parse_name_value_opt(&mut opts, opt)?;
                }
            } else {
                break;
            }
        }

        // read any leftover program arguments
        for opt in iter {
            parse_program_opt(&mut opts, opt)?;
        }
    }

    Ok(opts)
}

fn apply_unset_env_vars(opts: &Options<'_>) -> Result<(), Box<dyn UError>> {
    EnvAppData::default().drop_requested_env_names(opts)
}

fn apply_change_directory(opts: &Options<'_>) -> Result<(), Box<dyn UError>> {
    EnvAppData::default().enter_requested_directory(opts)
}

fn apply_specified_env_vars(opts: &Options<'_>) {
    // set specified env vars
    for (name, val) in &opts.sets {
        /*
         * set_var panics if name is an empty string
         * set_var internally calls setenv (on unix at least), while GNU env calls putenv instead.
         *
         * putenv returns successfully if provided with something like "=a" and modifies the environ
         * variable to contain "=a" inside it, effectively modifying the process' current environment
         * to contain a malformed string in it. Using GNU's implementation, the command `env =a`
         * prints out the malformed string and even invokes the child process with that environment.
         * This can be seen by using `env -i =a env` or `env -i =a cat /proc/self/environ`
         *
         * POSIX.1-2017 doesn't seem to mention what to do if the string is malformed (at least
         * not in "Chapter 8, Environment Variables" or in the definition for environ and various
         * exec*'s or in the description of env in the "Shell & Utilities" volume).
         *
         * It also doesn't specify any checks for putenv before modifying the environ variable, which
         * is likely why glibc doesn't do so. However, the first set_var argument cannot point to
         * an empty string or a string containing '='.
         *
         * There is no benefit in replicating GNU's env behavior, since it will only modify the
         * environment in weird ways
         */

        let name_txt = name.to_string_lossy();
        let val_txt = val.to_string_lossy();
        let _ = EnvAppData::default().ingest_text_pair(&name_txt, &val_txt);
        if name.is_empty() {
            show_warning!("no name specified for value {}", val.quote());
            continue;
        }
        env::set_var(name, val);
    }
}

